window.STORY_CHAPTERS["c3e19239bdc30316a"]={"id":"c3e19239bdc30316a","lines":[{"uid":"talk.vc.home_touch_yui_2#originalText","id":"talk.vc.home_touch_yui_2","speaker":{"cn":"结衣","en":"Yui","ja":"ユイ"},"text":{"cn":"真是的，很痒耶……","en":"Hey! That tickles!","ja":"もう、くすぐったいですよ……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_yui_3#originalText","id":"talk.vc.home_touch_yui_3","speaker":{"cn":"结衣","en":"Yui","ja":"ユイ"},"text":{"cn":"我要不要也跟大家一样，试着换个发型呢……","en":"Maybe I should change my hairstyle like everyone else.","ja":"私もみなさんみたいに髪型を変えてみようかな……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_yui_4#originalText","id":"talk.vc.home_touch_yui_4","speaker":{"cn":"结衣","en":"Yui","ja":"ユイ"},"text":{"cn":"爸爸对我的胸部有兴趣吗？","en":"Is my chest-area really that intriguing?","ja":"私の胸部に興味があるんですか?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_yui_5#originalText","id":"talk.vc.home_touch_yui_5","speaker":{"cn":"结衣","en":"Yui","ja":"ユイ"},"text":{"cn":"爸爸的手好大喔……被你这样抱着，我就会开始想睡觉。","en":"Your hands are so big... Just being in your arms like this makes me feel sleepy.","ja":"大きい手ですね……こうやって包まれてるとなんだか眠くなります"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_yui_6#originalText","id":"talk.vc.home_touch_yui_6","speaker":{"cn":"结衣","en":"Yui","ja":"ユイ"},"text":{"cn":"对妈妈做这种事情，她会很开心喔。","en":"You should do this to Mom instead. She would love it.","ja":"こういうのは、ママにやってあげると喜びますよ?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_yui_7#originalText","id":"talk.vc.home_touch_yui_7","speaker":{"cn":"结衣","en":"Yui","ja":"ユイ"},"text":{"cn":"要玩搔痒游戏吗？我不会输喔～！","en":"A tickle-fight? You asked for it!","ja":"くすぐりっこですか?負けませんよ～!"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_yui_8#originalText","id":"talk.vc.home_touch_yui_8","speaker":{"cn":"结衣","en":"Yui","ja":"ユイ"},"text":{"cn":"有什么事情吗？","en":"Any plans?","ja":"なにかご用ですか?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_yuna_1#originalText","id":"talk.vc.home_touch_yuna_1","speaker":{"cn":"YUNA","en":"Yuna","ja":"ユナ"},"text":{"cn":"呵呵，这个缎带很可爱吧。这是我最喜欢的缎带喔。","en":"Hehe, isn't this ribbon cute? It's my favorite.","ja":"ふふ、このリボンかわいいでしょ?私のお気に入りなんだ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_yuna_2#originalText","id":"talk.vc.home_touch_yuna_2","speaker":{"cn":"YUNA","en":"Yuna","ja":"ユナ"},"text":{"cn":"什么？要玩摸摸头游戏吗？嗯，好啊！来，你也把头靠过来吧！","en":"What is it, are you going to pet my head? Yes, it's fine! Yes, stick out your head as well!","ja":"なあに、頭なでっこするの?うん、いいよ!はい、そっちも頭出して!"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_yuna_3#originalText","id":"talk.vc.home_touch_yuna_3","speaker":{"cn":"YUNA","en":"Yuna","ja":"ユナ"},"text":{"cn":"嘿嘿……总觉得你这样对待我，好像还不错。","en":"Hehe... Well it's not like you disapprove of it, do you?","ja":"えへへ……なんかあなたにこうされるのあんまりイヤじゃないかも"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_yuna_4#originalText","id":"talk.vc.home_touch_yuna_4","speaker":{"cn":"YUNA","en":"Yuna","ja":"ユナ"},"text":{"cn":"呵呵，你知道吗？我的胸口正响着我的声音。","en":"Hehe, can't you hear my heart beating through my chest?","ja":"ふふ、胸で私の音が響いてるのが、わかる?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_yuna_5#originalText","id":"talk.vc.home_touch_yuna_5","speaker":{"cn":"YUNA","en":"Yuna","ja":"ユナ"},"text":{"cn":"啊哈哈，好痒喔！很好，看我怎么回敬你！","en":"Ahaha, I'm ticklish there! Ah, take it back!","ja":"あはは、くすぐったいよ!えーい、お返しだっ!"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_yuna_6#originalText","id":"talk.vc.home_touch_yuna_6","speaker":{"cn":"YUNA","en":"Yuna","ja":"ユナ"},"text":{"cn":"总～觉得啊，有种情色的氛围呢。那样不太好吧。","en":"This all feels so dirty... Shouldn't we stop?","ja":"なーんか、エッチな気配を感じるなあダメなんじゃないの、そういうの"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_yuna_7#originalText","id":"talk.vc.home_touch_yuna_7","speaker":{"cn":"YUNA","en":"Yuna","ja":"ユナ"},"text":{"cn":"……你摸那里的话，我，会觉得有点害羞。","en":"...Touching me there, is a little embarrassing, but...","ja":"……そこ触られるの、少し恥ずかしいんだけど"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_yuna_8#originalText","id":"talk.vc.home_touch_yuna_8","speaker":{"cn":"YUNA","en":"Yuna","ja":"ユナ"},"text":{"cn":"你真的很大胆呢。不过不行喔～大家都在看呢。","en":"You are actually quiet bold. But that's no good. Since everyone is watching.","ja":"実は大胆なんだね、あなたってでもダメだよーみんな見てるんだから"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_yuuki_1#originalText","id":"talk.vc.home_touch_yuuki_1","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"嘿嘿……你好像我姊姊。","en":"Hehehe. I feel like a big sister.","ja":"えへへ……なんか姉ちゃんみたい"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_yuuki_2#originalText","id":"talk.vc.home_touch_yuuki_2","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"这个装备适合我吗？","en":"Do I look okay in this costume?","ja":"この装備似合ってるかな? "},"kind":"dialogue"},{"uid":"talk.vc.home_touch_yuuki_3#originalText","id":"talk.vc.home_touch_yuuki_3","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"如果我像你一样高就好了。","en":"I wish I were as tall as you.","ja":"ボクもキミくらい背が高かったらよかったのになあ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_yuuki_4#originalText","id":"talk.vc.home_touch_yuuki_4","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"心脏的跳动，摸起来比预期的更鲜明对吧。","en":"I can feel your heartbeat more clearly than I expected.","ja":"心臓の鼓動って、思ったよりしっかり感じるよね"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_yuuki_5#originalText","id":"talk.vc.home_touch_yuuki_5","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"你的体温从胸口传达给我了。","en":"Your hands are so warm.","ja":"キミの体温が、胸から伝わってくるよ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_yuuki_6#originalText","id":"talk.vc.home_touch_yuuki_6","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"我的不怎么大，摸起来可能也没什么有趣吧？","en":"I'm not very big, so touching me might be boring.","ja":"ボクはあんまりおっきくないから触っても楽しくないかも? "},"kind":"dialogue"},{"uid":"talk.vc.home_touch_yuuki_7#originalText","id":"talk.vc.home_touch_yuuki_7","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"欸，你的摸法……很、很痒耶！","en":"Stop! Haha! That tickles!","ja":"ねえ、なんか触り方が……く、くすぐったいよ! "},"kind":"dialogue"},{"uid":"talk.vc.home_touch_yuuki_8#originalText","id":"talk.vc.home_touch_yuuki_8","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"嗯？怎么了？该不会，你是想跟我待在一起？","en":"Hm? What's wrong? Let me guess, you want to stay with me longer?","ja":"ん、どうしたの? もしかして、ボクと一緒にいたい? "},"kind":"dialogue"},{"uid":"talk.vc.home_touch_zink_1#originalText","id":"talk.vc.home_touch_zink_1","speaker":{"cn":"吉克","en":"Zink","ja":"ジンク"},"text":{"cn":"你干嘛啦，很痒耶！","en":"Haha! Hey! That tickles!","ja":"なんだよ、くすぐったいだろ!"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_zink_2#originalText","id":"talk.vc.home_touch_zink_2","speaker":{"cn":"吉克","en":"Zink","ja":"ジンク"},"text":{"cn":"有事就呼唤我的名字吧！","en":"If you need anything, call my name!","ja":"用があるなら、名前を呼べよ!"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_zink_3#originalText","id":"talk.vc.home_touch_zink_3","speaker":{"cn":"吉克","en":"Zink","ja":"ジンク"},"text":{"cn":"我身上有沾到脏东西吗？……我可不会跟你道谢喔。","en":"Is there some lint on me? Um...no thanks?","ja":"ゴミでも付いてるのか?……礼は言わないぞ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_zink_4#originalText","id":"talk.vc.home_touch_zink_4","speaker":{"cn":"吉克","en":"Zink","ja":"ジンク"},"text":{"cn":"怎么，你想用剑跟我一较高下吗！？","en":"What? You want a sword-fight?!","ja":"なんだ、剣で勝負する気か!?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_zink_5#originalText","id":"talk.vc.home_touch_zink_5","speaker":{"cn":"吉克","en":"Zink","ja":"ジンク"},"text":{"cn":"只要穿上铠甲，就能防御朝胸口而来的攻击嘛。","en":"All you need to protect your chest from attacks is a little armor.","ja":"鎧ってのを身につけてれば胸への攻撃も防げるんだよな"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_zink_8#originalText","id":"talk.vc.home_touch_zink_8","speaker":{"cn":"吉克","en":"Zink","ja":"ジンク"},"text":{"cn":"所以，我不是说要找我就叫名字吗！","en":"Again, call my name if you need anything!","ja":"だから、呼ぶなら名前を呼べって!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_administrator_1#originalText","id":"talk.vc.home_wait_administrator_1","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"最高司祭就在你面前。好了，还不跪下。","en":"You stand before the High Pontifex herself. Come and kneel.","ja":"目の前にいるのは最高司祭よさあ、跪きなさいな"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_administrator_2#originalText","id":"talk.vc.home_wait_administrator_2","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"你只要老老实实的，我就会赐予你珍藏的爱。","en":"If you stay still, I will bestow upon you my special love.","ja":"大人しくしていればとっておきの愛を与えてあげるわ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_administrator_3#originalText","id":"talk.vc.home_wait_administrator_3","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"让人界永远保持这种状态……就是我这个最高司祭的使命。","en":"Keeping the Human Realm as it is forever... That is my mission as the High Pontifex.","ja":"この人界をいつまでもこのままに……それが最高司祭である私の役目よ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_administrator_4#originalText","id":"talk.vc.home_wait_administrator_4","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"就算试图反抗我，也是白费力气。因为那种事情根本办不到。","en":"To resist me would be a fool’s errand. After all, resistance is impossible.","ja":"私に抗おう、なんて思っても無駄だって不可能だもの、そんなこと"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_administrator_9#originalText","id":"talk.vc.home_wait_administrator_9","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"清静很好呢，这样我就不会接收到多余的情报。","en":"I do love the quiet. Quietness keeps unnecessary feelings at bay.","ja":"静かなのはいいことね余計な情報が入ってこないから"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_administrator_10#originalText","id":"talk.vc.home_wait_administrator_10","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator"},"text":{"cn":"找你很久了。居然擅自快跑……看来需要重新调整呢。","en":"I have been looking for you. Fancy! Dashing away on your own. I think some readjusting is in order."},"kind":"dialogue"},{"uid":"talk.vc.home_wait_administrator_11#originalText","id":"talk.vc.home_wait_administrator_11","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator"},"text":{"cn":"是谁？居然连招呼都不打，就出现在我面前……","en":"Who's there? How dare you appear before me without introducing yourself!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_agil_1#originalText","id":"talk.vc.home_wait_agil_1","speaker":{"cn":"艾基尔","en":"Agil","ja":"エギル"},"text":{"cn":"你真的是喔，整天被卷入麻烦中的体质耶。","en":"Man, trouble seems to just follow you wherever you go.","ja":"まったくお前は、つくづくトラブルに巻き込まれる体質だな"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_agil_2#originalText","id":"talk.vc.home_wait_agil_2","speaker":{"cn":"艾基尔","en":"Agil","ja":"エギル"},"text":{"cn":"我是也想在这里开一间店……不过没有那什么《天职》，是不是不太好啊。","en":"I'd love to open shop here as well... But it seems like you really need one of those \"Callings\" here.","ja":"こっちでも店を出してみたいが……《天職》ってやつにつかないとやっぱりまずいのか"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_agil_3#originalText","id":"talk.vc.home_wait_agil_3","speaker":{"cn":"艾基尔","en":"Agil","ja":"エギル"},"text":{"cn":"人、商品、金钱，只要有这些，我到哪里都可以活下去。","en":"I can live anywhere as long as there's people, goods, and money.","ja":"人と商品と金、これさえあればオレはどこでだって生きていけるよ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_agil_4#originalText","id":"talk.vc.home_wait_agil_4","speaker":{"cn":"艾基尔","en":"Agil","ja":"エギル"},"text":{"cn":"你不要太乱来啊，也是有很多人在担心你的。","en":"Don't get too crazy, okay? Consider the many people who worry about you every day.","ja":"あんまり無茶はするなよお前を心配する人間も多いんだからな"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_agil_9#originalText","id":"talk.vc.home_wait_agil_9","speaker":{"cn":"艾基尔","en":"Agil","ja":"エギル"},"text":{"cn":"你要是有空，可不可以来我店里帮点忙？","en":"If you have some time on your hands, wanna help me with the shop?","ja":"暇だったら、少し店を手伝ってくれないか?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_agil_10#originalText","id":"talk.vc.home_wait_agil_10","speaker":{"cn":"艾基尔","en":"Agil"},"text":{"cn":"你最近都没来光顾啊，找到其他会常去的店了吗？","en":"I haven't seen ya around much. Did you find a place you like better than mine?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_agil_11#originalText","id":"talk.vc.home_wait_agil_11","speaker":{"cn":"艾基尔","en":"Agil"},"text":{"cn":"哎呀，打扰了。不过久违地看到你的脸，我就放心了。","en":"Oops, sorry to bother you. But it's a relief to see you're doing well."},"kind":"dialogue"},{"uid":"talk.vc.home_wait_airy_1#originalText","id":"talk.vc.home_wait_airy_1","speaker":{"cn":"升降员","en":"Operator","ja":"昇降係"},"text":{"cn":"您找我有什么事吗？","en":"Do you require my services?","ja":"わたくしにご用でしょうか"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_airy_2#originalText","id":"talk.vc.home_wait_airy_2","speaker":{"cn":"升降员","en":"Operator","ja":"昇降係"},"text":{"cn":"能这样承蒙您青睐……我很开心。","en":"I am truly honored to lay eyes on you.","ja":"こうしてお目にかかれて……うれしく思います"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_airy_3#originalText","id":"talk.vc.home_wait_airy_3","speaker":{"cn":"升降员","en":"Operator","ja":"昇降係"},"text":{"cn":"我有时会怀念起通往那座《云上庭园》的景色。","en":"Sometimes I think back fondly on the scenery that leads to the Cloudtop Garden.","ja":"時折、あの《雲上庭園》へと続く景色が懐かしくなります"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_airy_4#originalText","id":"talk.vc.home_wait_airy_4","speaker":{"cn":"升降员","en":"Operator","ja":"昇降係"},"text":{"cn":"外面世界的风，想必很舒服吧。","en":"The breeze in the outside world must feel very nice.","ja":"外の世界の風はとても気持ちがいいのでしょうね"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_airy_9#originalText","id":"talk.vc.home_wait_airy_9","speaker":{"cn":"升降员","en":"Operator","ja":"昇降係"},"text":{"cn":"如果您有任何命令，请尽管吩咐。","en":"If you have any commands for me, then please tell me.","ja":"なにかご命令があればなんなりとお申し付けくださいませ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_airy_10#originalText","id":"talk.vc.home_wait_airy_10","speaker":{"cn":"升降员","en":"Operator"},"text":{"cn":"……久疏问候。请问您有什么吩咐吗？","en":"Truly an honor to see you again. How may I serve you?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_airy_coverall_1#originalText","id":"talk.vc.home_wait_airy_coverall_1","speaker":{"ja":"エアリー"},"text":{"ja":"わたくしにご用でしょうか"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_airy_coverall_2#originalText","id":"talk.vc.home_wait_airy_coverall_2","speaker":{"cn":"艾莉","en":"Airy","ja":"エアリー"},"text":{"cn":"能这样承蒙您青睐……我很开心。","en":"I am truly honored to lay eyes on you.","ja":"こうしてお目にかかれて……うれしく思います"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_airy_coverall_3#originalText","id":"talk.vc.home_wait_airy_coverall_3","speaker":{"cn":"艾莉","en":"Airy","ja":"エアリー"},"text":{"cn":"我有时会怀念起通往那座《云上庭园》的景色。","en":"Sometimes I think back fondly on the scenery that leads to the Cloudtop Garden.","ja":"時折、あの《雲上庭園》へと続く景色が懐かしくなります"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_airy_coverall_4#originalText","id":"talk.vc.home_wait_airy_coverall_4","speaker":{"cn":"艾莉","en":"Airy","ja":"エアリー"},"text":{"cn":"外面世界的风，想必很舒服吧。","en":"The breeze in the outside world must feel very nice.","ja":"外の世界の風はとても気持ちがいいのでしょうね"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_airy_coverall_9#originalText","id":"talk.vc.home_wait_airy_coverall_9","speaker":{"cn":"艾莉","en":"Airy","ja":"エアリー"},"text":{"cn":"如果您有任何命令，请尽管吩咐。","en":"If you have any commands for me, then please tell me.","ja":"なにかご命令があればなんなりとお申し付けくださいませ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_alice_1#originalText","id":"talk.vc.home_wait_alice_1","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"我经常作梦。梦见被翠绿草木环绕的恬静村庄……","en":"Sometimes I have this dream... I'm in a peaceful village, surrounded in green.","ja":"時々、夢に見るのです緑の草木にかこまれた、のどかな村の風景を……"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_alice_2#originalText","id":"talk.vc.home_wait_alice_2","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"你最好记住，下次要是再骂我笨蛋，我就让你身首异处。","en":"If you call me stupid again, I can't guarantee your head will stay connected to your shoulders.","ja":"次に馬鹿と言ったら、お前の首と胴はつながっていないものと心得ておきなさい"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_alice_3#originalText","id":"talk.vc.home_wait_alice_3","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"老实说……我很不擅长应付元老长大人。我同时也认为，他那过度花俏的打扮已经脱离教会的本质。","en":"If I might be frank...I don't like the Prime Senator. I dislike his extravagant way of dress, and I think he has a screw loose.","ja":"元老長殿は……正直苦手です過度に飾り立てる姿も、教会の本質からは外れていると思いますし"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_alice_4#originalText","id":"talk.vc.home_wait_alice_4","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"真是不可思议……面对你，我居然会说出平常不会讲的话。","en":"Curious... You often say what others would not normally say.","ja":"不思議ですね……お前には普段は言わないようなことまで話してしまいます"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_alice_5#originalText","id":"talk.vc.home_wait_alice_5","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"我……我不擅长下厨。因为一直以来，我只专注在神圣术和剑技的训练上……","en":"I...am not a good cook. I devoted all my studies to the sword, or to Sacred Arts.","ja":"り……料理は苦手なのですずっと神聖術や剣技の稽古ばかりしていましたから……"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_alice_6#originalText","id":"talk.vc.home_wait_alice_6","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"端正仪容，是身为人最基本的礼仪。请你好歹带上一条手帕。","en":"A proper appearance is the minimum requirement of a polite person. Please, shut it away.","ja":"身だしなみは、人として最低限の礼儀です。手巾の1枚くらい携帯しておきなさい"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_alice_7#originalText","id":"talk.vc.home_wait_alice_7","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"请、请你不要那样看我，太令人害臊了啦……","en":"P-please, don't stare at me like that. You're embarrassing me!","ja":"そ、そんなに見ないでください恥ずかしいではありませんか……"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_alice_8#originalText","id":"talk.vc.home_wait_alice_8","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"你很出人意料呢。不过嘛，嗯，看你那样也是有趣。","en":"You are quite ridiculous... But I do enjoy watching.","ja":"お前は突拍子が無いですねでも、まあ、見ているのは楽しいです"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_alice_9#originalText","id":"talk.vc.home_wait_alice_9","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"你在发什么呆啊？我还以为你是一个在动脑前，就会先动身的男人呢。","en":"Why are you staring into space? I thought you were the sort of man who acted before he thought.","ja":"何をぼーっとしているのですお前は、頭を働かせる前に体が動いているような者と思っていました"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_alice_10#originalText","id":"talk.vc.home_wait_alice_10","speaker":{"cn":"爱丽丝","en":"Alice"},"text":{"cn":"好久不见了呢。你都在哪里玩疯啦……","en":"It has certainly been a while since I last saw you. You were probably slacking off somewhere."},"kind":"dialogue"},{"uid":"talk.vc.home_wait_alice_11#originalText","id":"talk.vc.home_wait_alice_11","speaker":{"cn":"爱丽丝","en":"Alice"},"text":{"cn":"也不是有要事找你，我只是……来监视你是不是又在做蠢事！","en":"I don't have a particular reason to see you... I merely came by to make sure you weren't up to something foolish again!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_alice_12#originalText","id":"talk.vc.home_wait_alice_12","speaker":{"cn":"爱丽丝","en":"Alice"},"text":{"cn":"又是新的一年了呢。我姑且，还是来跟你打声招呼。","en":"A new year is upon us. So I came to pay my respects, since it's proper."},"kind":"dialogue"},{"uid":"talk.vc.home_wait_alice_13#originalText","id":"talk.vc.home_wait_alice_13","speaker":{"cn":"爱丽丝","en":"Alice"},"text":{"cn":"我还在想你丢了什么东西过来，是豆子啊。那种东西连小孩都打不倒吧？","en":"Were you throwing...beans? Even against children, that isn't an effective attack."},"kind":"dialogue"},{"uid":"talk.vc.home_wait_alice_14#originalText","id":"talk.vc.home_wait_alice_14","speaker":{"cn":"爱丽丝","en":"Alice"},"text":{"cn":"你什么意思？那充满期待的眼神……我才没有准备送给心仪对象的点心！","en":"Why are your eyes filled with anticipation? I don't have any candy to give to a person I like!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_alice_15#originalText","id":"talk.vc.home_wait_alice_15","speaker":{"cn":"爱丽丝","en":"Alice"},"text":{"cn":"真是精致的人偶呢。想必是出自技艺高超的工匠之手吧？","en":"What incredible detail on those dolls. A highly skilled craftsman must have built them."},"kind":"dialogue"},{"uid":"talk.vc.home_wait_alice_16#originalText","id":"talk.vc.home_wait_alice_16","speaker":{"cn":"爱丽丝","en":"Alice"},"text":{"cn":"这、这是给我的回礼吗！？……好吧，我会收下，毕竟加以拒绝也是失礼……","en":"You have a thank you gift...for me? Well...thank you. I accept it. It would be rude to refuse."},"kind":"dialogue"},{"uid":"talk.vc.home_wait_alice_17#originalText","id":"talk.vc.home_wait_alice_17","speaker":{"cn":"爱丽丝","en":"Alice"},"text":{"cn":"4月笨蛋……？你又说我笨了是吧！给我乖乖坐好！","en":"April Fools? You called me a fool again, didn't you? Fix that bad habit of yours at once!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_alice_18#originalText","id":"talk.vc.home_wait_alice_18","speaker":{"cn":"爱丽丝","en":"Alice"},"text":{"cn":"长期休养啊？我并没有那么累……不过机会难得，就好好放松一下吧。","en":"A long vacation? I am not that tired, however... I'll take advantage of the opportunity and rest up."},"kind":"dialogue"},{"uid":"talk.vc.home_wait_alice_19#originalText","id":"talk.vc.home_wait_alice_19","speaker":{"cn":"爱丽丝","en":"Alice"},"text":{"cn":"雨是上天的恩赐。但下得这么久，倒也是令人困扰呢。","en":"Rain is a blessing from the heavens. However, excessive rain is a problem in and of itself."},"kind":"dialogue"},{"uid":"talk.vc.home_wait_alice_20#originalText","id":"talk.vc.home_wait_alice_20","speaker":{"cn":"爱丽丝","en":"Alice"},"text":{"cn":"这个就是矮竹吗？我还是第一次见到。真是不可思议的植物呢。","en":"This plant is called bamboo? What a strange plant. I've never seen it before."},"kind":"dialogue"},{"uid":"talk.vc.home_wait_alice_21#originalText","id":"talk.vc.home_wait_alice_21","speaker":{"cn":"爱丽丝","en":"Alice"},"text":{"cn":"我听说……夏至祭典是市井小民喜爱的祭典。……想必是相当有趣吧。","en":"Summer Festivals...I've heard commoners enjoy them. It does indeed sound enjoyable."},"kind":"dialogue"},{"uid":"talk.vc.home_wait_alice_22#originalText","id":"talk.vc.home_wait_alice_22","speaker":{"cn":"爱丽丝","en":"Alice"},"text":{"cn":"我想在那轮明月下，乘着《雨缘》翱翔。","en":"I would love to sit on Amayori and fly beneath that moon."},"kind":"dialogue"},{"uid":"talk.vc.home_wait_alice_23#originalText","id":"talk.vc.home_wait_alice_23","speaker":{"cn":"爱丽丝","en":"Alice"},"text":{"cn":"我刚刚看见有人穿着奇怪的衣服！那一定是暗之……咦，我弄错了？","en":"I witnessed a strangely-dressed intruder! He must be a Dark Agent! ...Oh, he isn't?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_alice_24#originalText","id":"talk.vc.home_wait_alice_24","speaker":{"cn":"爱丽丝","en":"Alice"},"text":{"cn":"每当看着染上艳丽色彩的树木，我就会感到不舍。因为它们完成了使命，即将飘逝而去……","en":"When I see red and orange on the trees, I feel melancholy. The poor leaves have served their purpose and now they are dying."},"kind":"dialogue"},{"uid":"talk.vc.home_wait_alice_25#originalText","id":"talk.vc.home_wait_alice_25","speaker":{"cn":"爱丽丝","en":"Alice"},"text":{"cn":"可真是热闹呢。这是要庆祝什么的宴会吗？","en":"How very festive. What are we celebrating?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_alice_child_1#originalText","id":"talk.vc.home_wait_alice_child_1","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"欸，今天的派味道如何？……好吃吗？","en":"Hey, how was the pie today? Was it yummy?","ja":"ねえ、今日のパイはどうだった? ……おいしかった? "},"kind":"dialogue"},{"uid":"talk.vc.home_wait_alice_child_2#originalText","id":"talk.vc.home_wait_alice_child_2","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"你今天也很有精神呢，可别兴奋过头啰。","en":"You're looking lively today. Try not to play too hard.","ja":"今日も元気ねえはしゃぎすぎないようにね"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_alice_child_3#originalText","id":"talk.vc.home_wait_alice_child_3","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"神圣术也是很方便的喔，只要发挥得好。","en":"But the Sacred Arts are useful, too. Depending on how you use it, of course.","ja":"神聖術って便利なものよ? 使い方によってはね"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_alice_child_4#originalText","id":"talk.vc.home_wait_alice_child_4","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"我今天的工作是监视你们，可没有在偷懒喔。","en":"My task today is to watch over you. I'm not slacking off, okay?","ja":"今日の仕事は、あんたたちの見張りなのさぼってるわけじゃないからね"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_alice_child_9#originalText","id":"talk.vc.home_wait_alice_child_9","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"怎么了？看你想东想西的很奇怪耶。","en":"Why the long face? Overthinking things doesn't suit you.","ja":"どうしたの? 考え事なんて似合わないんじゃない? "},"kind":"dialogue"},{"uid":"talk.vc.home_wait_alice_child_10#originalText","id":"talk.vc.home_wait_alice_child_10","speaker":{"cn":"爱丽丝","en":"Alice"},"text":{"cn":"有了有了，我正在找你呢！真是的，每次都马上就跑不见踪影！","en":"There you are! I've been looking all over! Why do you always run off like that?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_alice_child_11#originalText","id":"talk.vc.home_wait_alice_child_11","speaker":{"cn":"爱丽丝","en":"Alice"},"text":{"cn":"好久不见呢。你应该……没有忘记我吧？","en":"Long time no see. Don't tell me you've forgotten who I am?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_alice_integrator_wounded_1#originalText","id":"talk.vc.home_wait_alice_integrator_wounded_1","speaker":{"cn":"爱丽丝","en":"Alice"},"text":{"cn":"从此刻开始我会为我自己所追求的事物而战。","en":"From now on, I will fight for what I desire."},"kind":"dialogue"},{"uid":"talk.vc.home_wait_alice_integrator_wounded_2#originalText","id":"talk.vc.home_wait_alice_integrator_wounded_2","speaker":{"cn":"爱丽丝","en":"Alice"},"text":{"cn":"……我已经、没事了。为了我跟你所追求的事物，我要前进。","en":"... I'm fine. I will move forward. For what you and I desire."},"kind":"dialogue"},{"uid":"talk.vc.home_wait_alice_integrator_wounded_3#originalText","id":"talk.vc.home_wait_alice_integrator_wounded_3","speaker":{"cn":"爱丽丝","en":"Alice"},"text":{"cn":"你能听听我的决心吗？","en":"Can you hear my determination?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_alicia_1#originalText","id":"talk.vc.home_wait_alicia_1","speaker":{"cn":"亚丽莎","en":"Alicia","ja":"アリシャ"},"text":{"cn":"我好想研究你强劲的秘密喔～来来，你过来这里！","en":"I would love to research the source of your power. Come closer! Come on!","ja":"キミの強さのヒミツ、研究したいなーほらほら、こっちに来てヨ!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_alicia_2#originalText","id":"talk.vc.home_wait_alicia_2","speaker":{"cn":"亚丽莎","en":"Alicia","ja":"アリシャ"},"text":{"cn":"佣兵的话题还算数喔。我随时都可以！","en":"The mercenary deal isn't entirely off the table yet, FYI. I'm always game for it, whenever you are!","ja":"傭兵の話、まだ生きてるからネ?アタシはいつでもオッケーだヨ!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_alicia_3#originalText","id":"talk.vc.home_wait_alicia_3","speaker":{"cn":"亚丽莎","en":"Alicia","ja":"アリシャ"},"text":{"cn":"只要跟秘密兵器在一起，不论谁来都不会输呢！","en":"As long as I have Mr. Secret Weapon by my side, I can hold my own in any fight!","ja":"秘密兵器くんと一緒なら誰が来たって負けないネ!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_alicia_4#originalText","id":"talk.vc.home_wait_alicia_4","speaker":{"cn":"亚丽莎","en":"Alicia","ja":"アリシャ"},"text":{"cn":"来啦来啦，我们一起去散步嘛！说不定会有好玩的事发生！","en":"Come on, let's go on a walk! We might find something fun!","ja":"ほらほら、一緒にお散歩いこうヨ!なにかおもしろいことがあるかも!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_alicia_9#originalText","id":"talk.vc.home_wait_alicia_9","speaker":{"cn":"亚丽莎","en":"Alicia","ja":"アリシャ"},"text":{"cn":"啊～好闲喔～！我想睡觉了！","en":"Arrrgh, I'm so bored I'm getting sleepy!","ja":"あーん、ヒマだヨー!アタシ眠くなっちゃう!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_alicia_10#originalText","id":"talk.vc.home_wait_alicia_10","speaker":{"cn":"亚丽莎","en":"Alicia"},"text":{"cn":"哈啰～！好久不见了呢！","en":"Howdy! I haven't seen you in, like, forever!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_argo_1#originalText","id":"talk.vc.home_wait_argo_1","speaker":{"cn":"亚鲁戈","en":"Argo","ja":"アルゴ"},"text":{"cn":"你在这边似乎也很乱来呢。要活着回来啊。","en":"Looks like you're pushing yourself too hard here, too. Just come back alive, will you?","ja":"こっちでも無茶してるみたいダナ生きて帰ってこいヨ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_argo_2#originalText","id":"talk.vc.home_wait_argo_2","speaker":{"cn":"亚鲁戈","en":"Argo","ja":"アルゴ"},"text":{"cn":"就算我想收集情报，这个世界本身就太难以理解了……","en":"This world is too mysterious for me to gather intel.","ja":"ここじゃ、情報を集めようにも世界自体が複雑すぎるヨ……"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_argo_3#originalText","id":"talk.vc.home_wait_argo_3","speaker":{"cn":"亚鲁戈","en":"Argo","ja":"アルゴ"},"text":{"cn":"原来以前能够看见地图数据，是那么方便的功能啊。","en":"Being able to look up map data was a really useful game function.","ja":"マップデータが見られるってのは便利な機能だったんダナ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_argo_4#originalText","id":"talk.vc.home_wait_argo_4","speaker":{"cn":"亚鲁戈","en":"Argo","ja":"アルゴ"},"text":{"cn":"不论到了哪里，我都不会变喔。不论人在什么地方，我都是情报商人亚鲁戈啊。","en":"No matter what world I'm in, I'm still the same. I'm Argo the Informant.","ja":"別に、どこにいようがオレっちは変わらないヨ。どこにいても情報屋のアルゴ、サ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_argo_9#originalText","id":"talk.vc.home_wait_argo_9","speaker":{"cn":"亚鲁戈","en":"Argo","ja":"アルゴ"},"text":{"cn":"你沉思了很久呢，有什么事情让你担心吗？","en":"You look deep in thought. Something worrying you?","ja":"ずいぶん考えてるんダナなにか心配ごとでもあるのカ?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_argo_10#originalText","id":"talk.vc.home_wait_argo_10","speaker":{"cn":"亚鲁戈","en":"Argo"},"text":{"cn":"如果你需要情报，记得要找我喔！","en":"If you need intel, make sure you come to me."},"kind":"dialogue"},{"uid":"talk.vc.home_wait_argo_11#originalText","id":"talk.vc.home_wait_argo_11","speaker":{"cn":"亚鲁戈","en":"Argo"},"text":{"cn":"哎呀，不是这里啊？我正在收集情报，下次再聊吧。","en":"Oopsie. Not this one. I'm looking up intel right now. Catch ya later."},"kind":"dialogue"},{"uid":"talk.vc.home_wait_asuna_1#originalText","id":"talk.vc.home_wait_asuna_1","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"真是的……我一直很担心你耶！","en":"Honestly! I was so, so worried about you!","ja":"もう……ずっとずっと心配してたんだからね! "},"kind":"dialogue"},{"uid":"talk.vc.home_wait_asuna_2#originalText","id":"talk.vc.home_wait_asuna_2","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"那把剑……很适合你呢。","en":"That sword...it really suits you.","ja":"その剣……すごくよく似合ってるね"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_asuna_3#originalText","id":"talk.vc.home_wait_asuna_3","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"这里真是个美好的世界……要是没有战争的话，就能够悠闲地旅行呢。","en":"This world is very beautiful... If not for all the wars, I'd love to travel here.","ja":"ここはすごくステキな世界ね……戦争なんてなかったらゆっくり旅行でもしたいなあ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_asuna_4#originalText","id":"talk.vc.home_wait_asuna_4","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"不知道使用这个世界的材料，能不能重现对面的调味料呢？","en":"I wonder if I can use the materials in this world to create food from the real world?","ja":"こっちの世界の材料を使って向こう側の調味料とか再現できないかな?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_asuna_5#originalText","id":"talk.vc.home_wait_asuna_5","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"就算我说自己不是神明，大家也都不能理解啊……","en":"I'm not a god... But I doubt anyone would understand if I told them that.","ja":"神様なんかじゃない、って言っても、みんなわかってくれないのよね……"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_asuna_6#originalText","id":"talk.vc.home_wait_asuna_6","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"不论去到哪里，和谁在一起你果然还是原来的你啊","en":"No matter where you go or who you’re with, you never change.","ja":"どこに行っても、誰といても君はやっぱり君のままだよね"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_asuna_7#originalText","id":"talk.vc.home_wait_asuna_7","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"你、你那样盯着我看，我会害羞啦……","en":"D-don't stare at me like that. You're making me blush.","ja":"そ、そんなに見つめられたら照れちゃうよ……"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_asuna_8#originalText","id":"talk.vc.home_wait_asuna_8","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"今天久违地想跟你两个人私下好好聊天……","en":"It's been a while since you and I sat down for a nice long talk. Let's change that.","ja":"今日は久しぶりにゆっくりふたりきりで話がしたいな……"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_asuna_9#originalText","id":"talk.vc.home_wait_asuna_9","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"呵呵，我们两人很久没有像这样放松了呢。","en":"Hehe, it's been a while since you and I have had the chance to take it easy like this.","ja":"ふふ、こうやってふたりでのんびりするの久しぶりだよね"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_asuna_10#originalText","id":"talk.vc.home_wait_asuna_10","speaker":{"cn":"亚丝娜","en":"Asuna"},"text":{"cn":"你呀，接下来要去哪里呢？一定要先告诉我喔。","en":"Hey, where are we going next? Think it through first, okay?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_asuna_11#originalText","id":"talk.vc.home_wait_asuna_11","speaker":{"cn":"亚丝娜","en":"Asuna"},"text":{"cn":"最近都没有见到你呢。……我很寂寞喔。","en":"I haven't seen you around lately. Hey...I missed you."},"kind":"dialogue"},{"uid":"talk.vc.home_wait_asuna_12#originalText","id":"talk.vc.home_wait_asuna_12","speaker":{"cn":"亚丝娜","en":"Asuna"},"text":{"cn":"新年快乐。要不要一起去新年参拜呢？","en":"Happy New Year! Want to go to the shrine with me?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_asuna_13#originalText","id":"talk.vc.home_wait_asuna_13","speaker":{"cn":"亚丝娜","en":"Asuna"},"text":{"cn":"今天好冷呢～看日历，明明就快春天了啊……","en":"It sure is cold today. According to the calendar, it should already be spring..."},"kind":"dialogue"},{"uid":"talk.vc.home_wait_asuna_14#originalText","id":"talk.vc.home_wait_asuna_14","speaker":{"cn":"亚丝娜","en":"Asuna"},"text":{"cn":"辛苦了。今天是情人节……所以、那个，要不要一起过呢？","en":"Good job! Since today's Valentine's Day, do you want to, um, spend it with me?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_asuna_15#originalText","id":"talk.vc.home_wait_asuna_15","speaker":{"cn":"亚丝娜","en":"Asuna"},"text":{"cn":"今天是女儿节，所以我试着做了菱形蛋糕。我们一起吃吧？","en":"Since there's a festival today, I baked some chestnut cakes. Want to eat them with me?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_asuna_16#originalText","id":"talk.vc.home_wait_asuna_16","speaker":{"cn":"亚丝娜","en":"Asuna"},"text":{"cn":"呵呵，我来接你了。今天是白色情人节，我们不是约好了要一起过吗？","en":"Hehe, I came to get you. Remember? You promised we'd spend White Day together."},"kind":"dialogue"},{"uid":"talk.vc.home_wait_asuna_17#originalText","id":"talk.vc.home_wait_asuna_17","speaker":{"cn":"亚丝娜","en":"Asuna"},"text":{"cn":"你今天会骗我什么呢？","en":"So, how are you going to lie to me today?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_asuna_18#originalText","id":"talk.vc.home_wait_asuna_18","speaker":{"cn":"亚丝娜","en":"Asuna"},"text":{"cn":"难得有连假，要不要再一次外宿观星呢？","en":"Since we've got a few days off, want to go away and stargaze again?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_asuna_19#originalText","id":"talk.vc.home_wait_asuna_19","speaker":{"cn":"亚丝娜","en":"Asuna"},"text":{"cn":"讨厌，雨好大。就算撑伞，脚还是会淋湿啦。","en":"Man, I just hate the rain. Even with an umbrella, my feet still get wet."},"kind":"dialogue"},{"uid":"talk.vc.home_wait_asuna_20#originalText","id":"talk.vc.home_wait_asuna_20","speaker":{"cn":"亚丝娜","en":"Asuna"},"text":{"cn":"来，短签。陪我在上面写下愿望嘛。","en":"Here's your slip of paper for Tanabata. Now we can both write down our wishes to tie on the bamboo branch."},"kind":"dialogue"},{"uid":"talk.vc.home_wait_asuna_21#originalText","id":"talk.vc.home_wait_asuna_21","speaker":{"cn":"亚丝娜","en":"Asuna"},"text":{"cn":"呼～只是稍微在外面走走，就满身大汗了呢。真希望天气能快点变凉。","en":"Phew! Just walking outside for, like, 5 minutes gets me sweaty. I hope the weather cools down soon."},"kind":"dialogue"},{"uid":"talk.vc.home_wait_asuna_22#originalText","id":"talk.vc.home_wait_asuna_22","speaker":{"cn":"亚丝娜","en":"Asuna"},"text":{"cn":"团子摆好啰。要确实观赏过月亮后，才可以吃喔。","en":"I finished putting all the rice cakes in the display. Don't eat any until we've watched the moon for a while, okay?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_asuna_23#originalText","id":"talk.vc.home_wait_asuna_23","speaker":{"cn":"亚丝娜","en":"Asuna"},"text":{"cn":"Trick or Treat！不给糖，就要捣蛋啰！","en":"Trick or treat!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_asuna_24#originalText","id":"talk.vc.home_wait_asuna_24","speaker":{"cn":"亚丝娜","en":"Asuna"},"text":{"cn":"听说附近的公园可以赏枫，要不要一起去看看？","en":"I hear the autumn leaves are beautiful in the park. Want to check them out with me?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_asuna_25#originalText","id":"talk.vc.home_wait_asuna_25","speaker":{"cn":"亚丝娜","en":"Asuna"},"text":{"cn":"圣诞快乐！我试着做了烤鸡喔！要不要来我房间吃呢？","en":"Merry Christmas! I made a whole roasted chicken for the first time. Want to come to my room?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_azurica_1#originalText","id":"talk.vc.home_wait_azurica_1","speaker":{"cn":"阿滋利卡","en":"Azurika","ja":"アズリカ"},"text":{"cn":"你的修练有进展吗？可不能松懈了喔。","en":"Is your training proceeding well? You mustn't grow complacent.","ja":"修練は進んでいますか?気を抜いてはなりませんよ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_azurica_2#originalText","id":"talk.vc.home_wait_azurica_2","speaker":{"cn":"阿滋利卡","en":"Azurika","ja":"アズリカ"},"text":{"cn":"如果是你们，一定连这个世界的真理都能超越。","en":"I know that you are capable of overcoming this world's laws of nature.","ja":"あなた達なら、きっと世界の理すら超えていけるのでしょうね"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_azurica_3#originalText","id":"talk.vc.home_wait_azurica_3","speaker":{"cn":"阿滋利卡","en":"Azurika","ja":"アズリカ"},"text":{"cn":"……剑吗？我的技术已不足以展示。","en":"You want to see...me sword-fight? I am not skilled enough for an audience.","ja":"……剣ですか?もう、人に見せられるほどの腕ではありません"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_azurica_4#originalText","id":"talk.vc.home_wait_azurica_4","speaker":{"cn":"阿滋利卡","en":"Azurika","ja":"アズリカ"},"text":{"cn":"我只希望，众多练士都能变强。","en":"My one true wish is to help raise as many skilled sword fighters as I can.","ja":"たくさんの練士に強くなってほしい私の願いはそれだけです"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_azurica_9#originalText","id":"talk.vc.home_wait_azurica_9","speaker":{"cn":"阿滋利卡","en":"Azurika","ja":"アズリカ"},"text":{"cn":"能维持安静是很好，不过有点不像你呢。","en":"Being calm and quiet isn't a bad thing, but it seems a little bit out of character for you.","ja":"落ち着いているのはいいことですが少々あなたらしくないようですね"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_azurica_10#originalText","id":"talk.vc.home_wait_azurica_10","speaker":{"cn":"阿滋利卡","en":"Azurika"},"text":{"cn":"你在这里啊？请千万不要超过门禁时间。","en":"Oh, there you are. Be sure not to break your curfew."},"kind":"dialogue"},{"uid":"talk.vc.home_wait_bercouli_1#originalText","id":"talk.vc.home_wait_bercouli_1","speaker":{"cn":"贝尔库利","en":"Bercouli","ja":"ベルクーリ"},"text":{"cn":"那位最高司祭的肚子里，好像藏着什么主意啊。","en":"That High Pontifex does seem to have ulterior motives.","ja":"あの最高司祭猊下はどうも腹に一物ありそうなんだよなあ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_bercouli_2#originalText","id":"talk.vc.home_wait_bercouli_2","speaker":{"cn":"贝尔库利","en":"Bercouli","ja":"ベルクーリ"},"text":{"cn":"如果赢得过我，骑士长的位置就是你的了。","en":"If you defeat me, you may have my position as Commander.","ja":"もしオレに勝てたら騎士長の座はお前さんのモンだ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_bercouli_3#originalText","id":"talk.vc.home_wait_bercouli_3","speaker":{"cn":"贝尔库利","en":"Bercouli","ja":"ベルクーリ"},"text":{"cn":"你不用那么拘谨啦，放轻松点，放轻松。","en":"Come on, don't be so formal. Just relax.","ja":"そうかしこまらなくていいよ気を楽にしな、楽に"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_bercouli_4#originalText","id":"talk.vc.home_wait_bercouli_4","speaker":{"cn":"贝尔库利","en":"Bercouli","ja":"ベルクーリ"},"text":{"cn":"元老长……你要小心那家伙啊。他一定有在谋划什么诡计。","en":"The Prime Senator? Be wary of him. I know he's up to something.","ja":"元老長……あいつには気をつけろよ絶対なにか企んでやがる"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_bercouli_9#originalText","id":"talk.vc.home_wait_bercouli_9","speaker":{"cn":"贝尔库利","en":"Bercouli","ja":"ベルクーリ"},"text":{"cn":"我这个人啊，就是静不太下来。","en":"I've never been that good at \"being quiet.\"","ja":"静かにしてるってのはどうにも苦手なんだよなあ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_bercouli_10#originalText","id":"talk.vc.home_wait_bercouli_10","speaker":{"cn":"贝尔库利","en":"Bercouli"},"text":{"cn":"哎呀，你正在忙吗？那还真是抱歉。","en":"Oh, were you busy? Sorry about that."},"kind":"dialogue"},{"uid":"talk.vc.home_wait_bercouli_11#originalText","id":"talk.vc.home_wait_bercouli_11","speaker":{"cn":"贝尔库利","en":"Bercouli"},"text":{"cn":"好久不见。我还以为你忘记我了呢。","en":"Long time no see. I thought you'd forgotten about me."},"kind":"dialogue"},{"uid":"talk.vc.home_wait_cardinal_1#originalText","id":"talk.vc.home_wait_cardinal_1","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"怎么？你对书有兴趣吗？你要看是无妨，不过在那里的都是公理教会写的书喔。","en":"Oh, are you interested in books? You may read whatever you'd like, but the Axiom Church wrote those books.","ja":"なんじゃ、本に興味があるのか?読んでもいいが、そこにあるのは公理教会が書いたものじゃぞ?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_cardinal_2#originalText","id":"talk.vc.home_wait_cardinal_2","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"我一直在等待像你这样的人出现。","en":"I have waited all this time for a human such as you to appear.","ja":"お主のような人間が現れるのをわしはずっと待っておったのじゃ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_cardinal_3#originalText","id":"talk.vc.home_wait_cardinal_3","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"喂！不要在这里挥剑！很危险啊。","en":"Stop this! Don't swing your blade here! It's too dangerous.","ja":"これ!ここで剣を振り回すでない!危ないではないか"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_cardinal_4#originalText","id":"talk.vc.home_wait_cardinal_4","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"受不了，你可真是贪吃。拿去，包子给你吃。","en":"My, what a glutton you are! Here. Have another bun.","ja":"まったく、食い意地の張ったヤツじゃほれ、まんじゅうでも食え"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_cardinal_9#originalText","id":"talk.vc.home_wait_cardinal_9","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"难得你这么安静，在想事情吗？","en":"You are unusually quiet. Is there something on your mind?","ja":"珍しく静かじゃななにか思うところでもあるのか?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_cardinal_10#originalText","id":"talk.vc.home_wait_cardinal_10","speaker":{"cn":"卡迪娜尔","en":"Cardinal"},"text":{"cn":"哼，像这样从远处干涉，对我来说也是易如反掌。","en":"Hmm... It would seem that meddling from afar is my forte."},"kind":"dialogue"},{"uid":"talk.vc.home_wait_cardinal_11#originalText","id":"talk.vc.home_wait_cardinal_11","speaker":{"cn":"卡迪娜尔","en":"Cardinal"},"text":{"cn":"好久不见。你还记得术式吗？","en":"Long time no see. Have you memorized the incantation?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_dakira_1#originalText","id":"talk.vc.home_wait_dakira_1","speaker":{"cn":"达基拉","en":"Dakira","ja":"ダキラ"},"text":{"cn":"身为四把剑的其中一员，我早已做好随时丧命的觉悟了。","en":"As one of the Four Whirling Blades, I am ready to die at any instant.","ja":"四本の剣の一振りとしていつでも命を捨てる覚悟はできております"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_dakira_2#originalText","id":"talk.vc.home_wait_dakira_2","speaker":{"cn":"达基拉","en":"Dakira","ja":"ダキラ"},"text":{"cn":"您不叫我的名字也没关系。","en":"I don't mind if you don't call me by name.","ja":"名前など、呼んでくださらなくても構わないのです"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_dakira_3#originalText","id":"talk.vc.home_wait_dakira_3","speaker":{"cn":"达基拉","en":"Dakira","ja":"ダキラ"},"text":{"cn":"我们是四人为一体。无论是怎么样的命令，都使命必达。","en":"The four of us shall carry out any command, as a unit.","ja":"我らは四にして一いかなる命令でも遂行してみせます"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_dakira_4#originalText","id":"talk.vc.home_wait_dakira_4","speaker":{"cn":"达基拉","en":"Dakira","ja":"ダキラ"},"text":{"cn":"如果您要出门，无论是何处都请让我跟随！","en":"If you are going out somewhere, please let me come with you!","ja":"お出かけになるのであればどこへなりともお供させてください!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_dakira_9#originalText","id":"talk.vc.home_wait_dakira_9","speaker":{"cn":"达基拉","en":"Dakira","ja":"ダキラ"},"text":{"cn":"……我随时都在您身边，有任何事都请告诉我。","en":"I will always be by your side. Call on me if you ever need anything.","ja":"……いつでもお側におります何かあれば、お申し付けください"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_dakira_10#originalText","id":"talk.vc.home_wait_dakira_10","speaker":{"cn":"达基拉","en":"Dakira"},"text":{"cn":"怎么了？找我们四旋剑有什么事吗？","en":"What is it? Do you require the services of the Four Whirling Blades?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_deathgun_1#originalText","id":"talk.vc.home_wait_deathgun_1","speaker":{"cn":"死枪","en":"Death Gun","ja":"デス・ガン"},"text":{"cn":"我跟、这把枪、的名字是……《死枪》。是让你们死去的存在。","en":"Me and my gun are called... \"Death Gun\". My existance will be the death of you all.","ja":"俺と、この銃の、名前は……《デス・ガン》お前らに死をもたらす存在だ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_deathgun_2#originalText","id":"talk.vc.home_wait_deathgun_2","speaker":{"cn":"死枪","en":"Death Gun","ja":"デス・ガン"},"text":{"cn":"我的身影、绝不会、被任何人、捕捉得到。","en":"Noone will ever be able to catch me.","ja":"俺の姿は、誰にも、決して捕らえることはできない"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_deathgun_3#originalText","id":"talk.vc.home_wait_deathgun_3","speaker":{"cn":"死枪","en":"Death Gun","ja":"デス・ガン"},"text":{"cn":"还没、结束。惨剧、一定、不会结束……It's show time.","en":"This isn't, over. This tragedy will never end... It's show time.","ja":"終わって、いない惨劇は、決して、終わらない……イッツ・ショウ・タイム"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_deathgun_4#originalText","id":"talk.vc.home_wait_deathgun_4","speaker":{"cn":"死枪","en":"Death Gun","ja":"デス・ガン"},"text":{"cn":"无法用、自已的意志、来杀人、的人，是不会拥有、真正的强大。","en":"I don't believe in killing people. I do not use my true strength on people.","ja":"自らの、意思で、人を、殺せない者に、本当の、強さは宿らない"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_deathgun_9#originalText","id":"talk.vc.home_wait_deathgun_9","speaker":{"cn":"死枪","en":"Death Gun","ja":"デス・ガン"},"text":{"cn":"哼、哼、哼。感受到、恐惧。你、怕、我、吗？","en":"Heh heh. Feel frightened? A-Afraid of m-me?","ja":"ク、ク、ク恐怖を、感じる恐れて、いるのか、俺を"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_deusolbert_1#originalText","id":"talk.vc.home_wait_deusolbert_1","speaker":{"cn":"迪索尔巴德","en":"Deusolbert","ja":"デュソルバート"},"text":{"cn":"你的剑技……居然连我都无法看穿。","en":"Inconceivable. That even I could not grasp your skill with the sword...","ja":"貴様の剣技……この我ですら捉えられぬとは"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_deusolbert_2#originalText","id":"talk.vc.home_wait_deusolbert_2","speaker":{"cn":"迪索尔巴德","en":"Deusolbert","ja":"デュソルバート"},"text":{"cn":"在这把《炽焰弓》面前，就连千军万马都将被烧尽。","en":"Even an army of ten thousand is mere ash when faced with my Conflagration Bow.","ja":"この《熾焰弓》の前には万の大軍すら燃え尽きるだろう"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_deusolbert_3#originalText","id":"talk.vc.home_wait_deusolbert_3","speaker":{"cn":"迪索尔巴德","en":"Deusolbert","ja":"デュソルバート"},"text":{"cn":"我也想要赶紧从最高司祭那里，领受新的赴任地点。","en":"I, too, am eager to receive a new post from the High Pontifex.","ja":"早く我も、新たな任地を最高司祭猊下から賜りたいものだ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_deusolbert_4#originalText","id":"talk.vc.home_wait_deusolbert_4","speaker":{"cn":"迪索尔巴德","en":"Deusolbert","ja":"デュソルバート"},"text":{"cn":"你的确是很另类……但是，似乎还有更加深藏不露之处。","en":"You are indeed alien... But that is not all. There's more than meets the eye.","ja":"貴様は確かに異質だが……それだけではない何かがあるようだ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_deusolbert_9#originalText","id":"talk.vc.home_wait_deusolbert_9","speaker":{"cn":"迪索尔巴德","en":"Deusolbert","ja":"デュソルバート"},"text":{"cn":"没事的话，我就要回去着手任务了。","en":"If you have no business with me, then I shall return to my post.","ja":"用事がないのであれば我は任務に戻るとしよう"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_deusolbert_10#originalText","id":"talk.vc.home_wait_deusolbert_10","speaker":{"cn":"迪索尔巴德","en":"Deusolbert"},"text":{"cn":"好久不见了。我很期待和你共赴战场的那一天。","en":"Long time no see. I look forward to the day when we stand together on the battlefield."},"kind":"dialogue"},{"uid":"talk.vc.home_wait_deusolbert_11#originalText","id":"talk.vc.home_wait_deusolbert_11","speaker":{"cn":"迪索尔巴德","en":"Deusolbert"},"text":{"cn":"嗯……我听说这一带有人抵触了禁忌目录……","en":"Hmm...I received word that someone was breaking the Taboo Index in this general vicinity."},"kind":"dialogue"},{"uid":"talk.vc.home_wait_diavel_1#originalText","id":"talk.vc.home_wait_diavel_1","speaker":{"cn":"迪亚贝尔","en":"Diavel","ja":"ディアベル"},"text":{"cn":"差不多该出任务了吧？","en":"Wanna go on a quest?","ja":"そろそろクエストに行かないか?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_diavel_2#originalText","id":"talk.vc.home_wait_diavel_2","speaker":{"cn":"迪亚贝尔","en":"Diavel","ja":"ディアベル"},"text":{"cn":"我才正好想着要跟你多说说话呢。","en":"I was just thinking I'd like to talk to you.","ja":"もっと君と話がしたいとそう思っていたところだ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_diavel_3#originalText","id":"talk.vc.home_wait_diavel_3","speaker":{"cn":"迪亚贝尔","en":"Diavel","ja":"ディアベル"},"text":{"cn":"真希望可以活得像你一样……我时常会这么想啊。","en":"Sometimes I wish I could live like you.","ja":"君みたいに生きられたらいいな……時々そう思うよ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_diavel_4#originalText","id":"talk.vc.home_wait_diavel_4","speaker":{"cn":"迪亚贝尔","en":"Diavel","ja":"ディアベル"},"text":{"cn":"无论何时都要来找我喔！我一定会帮上忙的。","en":"Call on me anytime! I promise I'll help.","ja":"いつでも呼んでくれよ!必ず力になるから"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_diavel_9#originalText","id":"talk.vc.home_wait_diavel_9","speaker":{"cn":"迪亚贝尔","en":"Diavel","ja":"ディアベル"},"text":{"cn":"……这种沉静的氛围，偶尔来个一次也还算不错吧。","en":"Sometimes I don't mind a little peace and quiet.","ja":"……こういう静かな雰囲気もたまには悪くないかな"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_diavel_10#originalText","id":"talk.vc.home_wait_diavel_10","speaker":{"cn":"迪亚贝尔","en":"Diavel"},"text":{"cn":"你还记得我吗？希望你偶尔能想起我。","en":"Do you remember me? It'd be nice if you thought of me, once in a while."},"kind":"dialogue"},{"uid":"talk.vc.home_wait_dil_1#originalText","id":"talk.vc.home_wait_dil_1","speaker":{"cn":"蒂伊‧艾‧耶尔","en":"Dee Eye Ell","ja":"ディー・アイ・エル"},"text":{"cn":"我早晚会成为世界的王，为此，能利用的东西，必须物尽其用。","en":"Eventually, I will be the queen of this world. I will do whatever it takes to make that come true...","ja":"私はいずれ世界の王になるそのために利用できるものはすべて利用するわ……"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_dil_2#originalText","id":"talk.vc.home_wait_dil_2","speaker":{"cn":"蒂伊‧艾‧耶尔","en":"Dee Eye Ell","ja":"ディー・アイ・エル"},"text":{"cn":"无论是皇帝陛下还是人界军，我都可以用术式歼灭给你看。","en":"His majesty the Emperor, the armies of the Human Empire... I will sweep them all away with my technique. You just wait and see.","ja":"皇帝陛下、人界軍など私の術式ですべて薙ぎ払ってご覧に入れますわ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_dil_3#originalText","id":"talk.vc.home_wait_dil_3","speaker":{"cn":"蒂伊‧艾‧耶尔","en":"Dee Eye Ell","ja":"ディー・アイ・エル"},"text":{"cn":"猪和巨人，还有哥布尔……真是的，这种丑陋的异类能不能不要进入我的视野。","en":"These giant pigs, and these goblins... All these sub-beings! I want them out of my sight!","ja":"豚に巨人、そしてゴブリン……まったく、醜い亜人は私の視界に入らないでほしいわ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_dil_4#originalText","id":"talk.vc.home_wait_dil_4","speaker":{"cn":"蒂伊‧艾‧耶尔","en":"Dee Eye Ell","ja":"ディー・アイ・エル"},"text":{"cn":"面对暗黑将军必须得小心。因为那个男人，就像被奇怪的想法依附着一样……","en":"Don't get careless with that Dark Territory general. That man is possessed by a strange idea...","ja":"暗黒将軍には油断なりませんあの男は、おかしな考えに取り憑かれているようですから…"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_dil_9#originalText","id":"talk.vc.home_wait_dil_9","speaker":{"cn":"蒂伊‧艾‧耶尔","en":"Dee Eye Ell","ja":"ディー・アイ・エル"},"text":{"cn":"有命令的时候，请呼唤我的名字。我会马上出现在你的眼前。","en":"When there's an order, make sure to call out my name. I will be there at a moments notice.","ja":"ご命令の際は、私の名前をお呼びくださいすぐ眼前に参上いたします"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_edith_1#originalText","id":"talk.vc.home_wait_edith_1","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"欸，今天要不要一起出门？反正也没有任务吧？","en":"Would you like to go out today? You have no other duties, do you?","ja":"ね、今日は一緒にお出かけしない? 任務は別にないでしょ? "},"kind":"dialogue"},{"uid":"talk.vc.home_wait_edith_2#originalText","id":"talk.vc.home_wait_edith_2","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"我一直很想见你呢。嗯～打起精神了！","en":"Just the person I wanted to see! You know, you cheer me up!","ja":"あなたの顔が見たかったのようーん、元気出るわ! "},"kind":"dialogue"},{"uid":"talk.vc.home_wait_edith_3#originalText","id":"talk.vc.home_wait_edith_3","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"今天打扮奇怪的元老长不在吗？难怪空气这么清新。","en":"Is that stupidly dressed Prime Senator not around today? So, that explains why the atmosphere is so good!","ja":"今日は変な格好の元老長はいないの? それなら空気がキレイだわ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_edith_4#originalText","id":"talk.vc.home_wait_edith_4","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"我的剑是暗之剑。任何人都无法触碰……说笑的。","en":"Mine is a sword of darkness. No one shall be permitted to touch it! Haha. Just kidding.","ja":"あたしの剣は、闇の剣よ誰にも触れることはできない……なんてね"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_edith_5#originalText","id":"talk.vc.home_wait_edith_5","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"居然敢闯入本公理教会……世上还真有不要命的家伙呢。","en":"Fancy, infiltrating the great Axiom Church! You must have a death wish.","ja":"この公理教会に乗り込んでくるなんて……命知らずの連中もいるもんね"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_edith_6#originalText","id":"talk.vc.home_wait_edith_6","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"金木樨很适合你呢。因为，那种花很香嘛。","en":"Osmanthus is perfect for you. Those flowers are so sweet and fragrant.","ja":"金木犀ってあなたにピッタリだって、すごくいい匂いがするもの、あの花"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_edith_7#originalText","id":"talk.vc.home_wait_edith_7","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"你在那里啊。……我突然好想见你……","en":"Oh, there you are. I wanted to see you for some reason...","ja":"そこにいたのねなんだか会いたくなっちゃって……"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_edith_8#originalText","id":"talk.vc.home_wait_edith_8","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"只要你不嫌弃，我的胸膛随时可以借给你用。你的眼泪，我会承受下来。","en":"If you ever need a shoulder to cry on, mine is always available.","ja":"あたしの胸でよかったらいつでも貸してあげる。あなたの涙くらい、受け止められるから"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_edith_9#originalText","id":"talk.vc.home_wait_edith_9","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"干嘛苦着一张脸？多想想快乐的事情吧！","en":"Why the long face? Come on, think positively!","ja":"なに難しい顔してるの? もっと楽しいこと考えましょう!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_edith_10#originalText","id":"talk.vc.home_wait_edith_10","speaker":{"cn":"伊迪丝","en":"Eydis"},"text":{"cn":"哎呀，对不起。我没有在监视你啦，你别在意。","en":"Oh dear, I'm sorry. But don't worry, I wasn't spying on you."},"kind":"dialogue"},{"uid":"talk.vc.home_wait_edith_11#originalText","id":"talk.vc.home_wait_edith_11","speaker":{"cn":"伊迪丝","en":"Eydis"},"text":{"cn":"好久不见了。见不到你我好寂寞喔～","en":"So good to see you again! I missed you."},"kind":"dialogue"},{"uid":"talk.vc.home_wait_edith_12#originalText","id":"talk.vc.home_wait_edith_12","speaker":{"cn":"伊迪丝","en":"Eydis"},"text":{"cn":"我来拜年了。今年也请多多指教一整年啰。","en":"I came to wish you a Happy New Year."},"kind":"dialogue"},{"uid":"talk.vc.home_wait_edith_13#originalText","id":"talk.vc.home_wait_edith_13","speaker":{"cn":"伊迪丝","en":"Eydis"},"text":{"cn":"……你戴着面具在干嘛？喔～原来就是那样的仪式。稍微吓到我了。","en":"Why are you wearing a mask? Ohhh, I see. It's a ceremony. You gave me a little fright there!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_edith_14#originalText","id":"talk.vc.home_wait_edith_14","speaker":{"cn":"伊迪丝","en":"Eydis"},"text":{"cn":"听说今天是送心仪对象礼物的日子！所以你就收下吧！","en":"I hear today is the day where one gives candy to their beloved! So, here you go!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_edith_15#originalText","id":"talk.vc.home_wait_edith_15","speaker":{"cn":"伊迪丝","en":"Eydis"},"text":{"cn":"这个人偶好精致，很漂亮呢。喔喔，原来是装饰成婚礼的样子啊。","en":"What delicate, pretty dolls. Oh, now I see it. This is set up like a wedding."},"kind":"dialogue"},{"uid":"talk.vc.home_wait_edith_16#originalText","id":"talk.vc.home_wait_edith_16","speaker":{"cn":"伊迪丝","en":"Eydis"},"text":{"cn":"咦！？送出去，还会有回礼……我好开心，谢谢！","en":"What?! A gift...for a gift? Thank you. That was so sweet of you."},"kind":"dialogue"},{"uid":"talk.vc.home_wait_edith_17#originalText","id":"talk.vc.home_wait_edith_17","speaker":{"cn":"伊迪丝","en":"Eydis"},"text":{"cn":"谎话……要骗人啊？如果可以开心地说谎，或许也不错呢。","en":"A day of lying, eh? If I could tell carefree lies, that might not be a bad thing indeed."},"kind":"dialogue"},{"uid":"talk.vc.home_wait_edith_18#originalText","id":"talk.vc.home_wait_edith_18","speaker":{"cn":"伊迪丝","en":"Eydis"},"text":{"cn":"真希望公理教会也能实施长假耶……虽然因为有黑暗领域在，也没办法挑三拣四。","en":"I wish the Axiom Church had long vacations. But we can't rest while the Dark Territory exists."},"kind":"dialogue"},{"uid":"talk.vc.home_wait_edith_19#originalText","id":"talk.vc.home_wait_edith_19","speaker":{"cn":"伊迪丝","en":"Eydis"},"text":{"cn":"现在正下着雨，所以不必勉强外出啦。一起躲雨吧？","en":"Don't force yourself to go outside; it's raining. Would you like to stay in with me?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_edith_20#originalText","id":"talk.vc.home_wait_edith_20","speaker":{"cn":"伊迪丝","en":"Eydis"},"text":{"cn":"这是要做什么的？将愿望传给上天……？那就放到塔顶吧！","en":"What are you doing with those papers? You're offering wishes to the heavens? Then we should display them on the tower's roof!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_edith_21#originalText","id":"talk.vc.home_wait_edith_21","speaker":{"cn":"伊迪丝","en":"Eydis"},"text":{"cn":"我想去夏至祭典，所以来接你了。别担心，藏好集成骑士的身分就行。","en":"I thought I'd go to the Summer Festival, so I came to take you with me. Don't worry, I'll just hide my identity as an Integrity Knight."},"kind":"dialogue"},{"uid":"talk.vc.home_wait_edith_22#originalText","id":"talk.vc.home_wait_edith_22","speaker":{"cn":"伊迪丝","en":"Eydis"},"text":{"cn":"月亮高挂的夜晚，侦查就会变得很困难。因为容易被敌人发现嘛。","en":"Spying is always most difficult when the moon is out. It's easy for the enemy to spot me."},"kind":"dialogue"},{"uid":"talk.vc.home_wait_edith_23#originalText","id":"talk.vc.home_wait_edith_23","speaker":{"cn":"伊迪丝","en":"Eydis"},"text":{"cn":"不好了！外面有一堆打扮怪异的人！","en":"Alert! Alert! Strange-looking creatures spotted outside the gate!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_edith_24#originalText","id":"talk.vc.home_wait_edith_24","speaker":{"cn":"伊迪丝","en":"Eydis"},"text":{"cn":"从飞龙身上看下去，染上色彩的山林非常美丽喔。一起去看看吧？","en":"The mountains, dyed in red leaves, look so beautiful from a dragon's back. Would you care to join me for a ride?"},"kind":"dialogue"}]};
